import { describe, expect, it } from 'vitest';
import { assertConsistent, loadFieldMapData } from './load';
import { computeFieldMap } from './stats';
import type { FieldMapData } from './types';

/**
 * These assert invariants, not counts. The payload is regenerated by
 * scripts/4-classify.mjs whenever the export or the taxonomy changes, so
 * pinning exact numbers here would mean editing tests on every re-run — which
 * trains you to update the expectation instead of reading the failure.
 */
describe('loadFieldMapData', () => {
  it('loads anonymized fixture data by default', async () => {
    const { conversations } = await loadFieldMapData();
    expect(conversations.map((c) => c.id)).toContain('fixture-research-session');
  });

  it('loads private data only when a private source is provided', async () => {
    const privateData: FieldMapData = {
      topics: [{ id: 'private', label: 'Private' }],
      conversations: [
        {
          id: 'private-conversation',
          title: 'Private conversation',
          date: '2026-01-01T00:00:00.000Z',
          topicIds: ['private'],
          messages: 2,
          model: null,
          opening: 'Private opening',
        },
      ],
    };

    const data = await loadFieldMapData({
      privateDataUrl: '/__private/field-map-data.json',
      fetchData: async () => privateData,
    });

    expect(data.conversations.map((c) => c.id)).toEqual(['private-conversation']);
  });

  it('loads and passes the consistency check', async () => {
    await expect(loadFieldMapData()).resolves.toBeDefined();
  });

  it('declares topics with unique ids and labels', async () => {
    const { topics } = await loadFieldMapData();
    expect(topics.length).toBeGreaterThan(1);
    expect(new Set(topics.map((t) => t.id)).size).toBe(topics.length);
    expect(topics.every((t) => t.label.trim().length > 0)).toBe(true);
  });

  it('gives every conversation a unique id and a valid date', async () => {
    const { conversations } = await loadFieldMapData();
    expect(conversations.length).toBeGreaterThan(0);
    expect(new Set(conversations.map((c) => c.id)).size).toBe(conversations.length);
    for (const c of conversations) {
      expect(Number.isNaN(Date.parse(c.date))).toBe(false);
    }
  });

  it('carries the fields the panel needs beyond title and date', async () => {
    const { conversations } = await loadFieldMapData();
    for (const c of conversations) {
      expect(typeof c.messages).toBe('number');
      expect(typeof c.opening).toBe('string');
    }
  });

  it('leaves some conversations untagged and tags the rest', async () => {
    const { topics, conversations } = await loadFieldMapData();
    const map = computeFieldMap(topics, conversations);
    // N counts only tagged conversations, so it must be a strict subset.
    expect(map.total).toBeGreaterThan(0);
    expect(map.total).toBeLessThanOrEqual(conversations.length);
    // Every declared topic should actually be used by the classifier.
    for (const topic of topics) {
      expect(map.counts[topic.id]).toBeGreaterThan(0);
    }
  });

  it('assigns more than one topic to some conversations', async () => {
    const { conversations } = await loadFieldMapData();
    expect(conversations.some((c) => c.topicIds.length > 1)).toBe(true);
  });
});

describe('assertConsistent', () => {
  const one = (topicIds: string[]): FieldMapData => ({
    topics: [{ id: 'a', label: 'A' }],
    conversations: [
      {
        id: 'c1',
        title: 'c1',
        date: '2024-01-01T00:00:00.000Z',
        topicIds,
        messages: 2,
        model: null,
        opening: '',
      },
    ],
  });

  it('rejects a conversation citing an undeclared topic', () => {
    expect(() => assertConsistent(one(['a', 'ghost']))).toThrow(/ghost/);
  });

  it('names every undeclared topic, once each', () => {
    const data = one(['ghost', 'ghost', 'wraith']);
    expect(() => assertConsistent(data)).toThrow(/undeclared topic ids: ghost, wraith$/);
  });

  it('accepts a conversation with no topics', () => {
    expect(() => assertConsistent(one([]))).not.toThrow();
  });
});
